mapper.select:
select case when qb.qc_user_name = '' then '尚未分配' else qb.qc_user_name end as qcUserName, count(0) as qcTotalQty, sum (case when qb.qc_status = 'finishQc' then 1 else 0 end) as qcFinishQty, sum (case when qb.qc_status = 'waitQc' then 1 else 0 end) as qcWaitQty, sum (case when qb.qc_status = 'exemption' then 1 else 0 end) as qcFreeQty, sum (case when wr.approve_time::timestamp + INTERVAL '1 DAY' >= qb.qc_finish_time then 1 else 0 end) as qcTimelyQty, sum (case when qb.qc_finish_time > wr.approve_time::timestamp + INTERVAL '1 DAY' and qb.qc_status in ('finishQc','exemption') then 1 else 0 end) as qcTimeOutQty, sum (case when now() > wr.approve_time::timestamp + INTERVAL '1 DAY' and qb.qc_status = 'waitQc' then 1 else 0 end) as unQcTimeOutQty from qc_info qb left join po_receive wr on qb.source_id = wr.id and wr.is_deleted = false
qb.is_deleted = false and qb.qc_date is not null
and qb.qc_date >= #{params.dateList[0]} and (#{params.dateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > qb.qc_date
${params.param}
${params.param}
group by qb.qc_user_id,qc_user_name

SELECT qb.id, qb.code, qb.qc_dept_id, qb.qc_dept_name, qb.qc_user_id, qb.qc_user_name, qb.purchase_order_id, qb.purchase_order_code,qb.qc_status, qb.qc_date,qb.supplier_id,qb.warehouse_id, qb.create_user_name,qb.create_time, qi.qc_type,qi.is_inside, qp.sku_id,qp.sku_no,qi.total_qty, qi.qc_qty,qi.qc_good_qty, qi.qc_bad_qty,qi.qc_result, qi.handle_mode_dict, qi.bad_description, qi.qc_good_rate*100 AS qcGoodRate, qi.qc_bad_rate*100 AS qcBadRate FROM qc_info qb LEFT JOIN qc_result qi ON qb.id=qi.main_id AND qi.is_deleted=FALSE LEFT JOIN qc_product qp ON qp.main_id=qi.main_id AND qp.is_deleted=FALSE WHERE qb.is_deleted=FALSE
AND qb.qc_status=#{params.searchType}
AND qb.purchase_order_code ILIKE concat('%', #{params.purchaseOrderCode} ,'%')
AND qb.code ilike concat('%', #{params.code} ,'%')
AND qp.sku_no IN
#{skuNo}
AND qb.qc_user_id IN
#{qcUserId}
AND qb.qc_status IN
#{qcStatus}
AND qi.qc_type =#{params.qcType}
AND qi.is_inside =#{params.isInside}
AND qb.supplier_id IN
#{supplierId}
AND qb.warehouse_id IN
#{warehouseId}
AND qi.qc_result IN
#{qcResult}
AND qi.handle_mode_dict IN
#{handleMode}
AND qb.create_user_id IN
#{createUserId}
AND qb.create_time >= #{params.createTimeList[0]} and (#{params.createTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > qb.create_time
${params.param}
ORDER BY qb.create_time DESC

SELECT qb.id, qb.code, qb.qc_dept_id, qb.qc_dept_name, qb.qc_user_id, qb.qc_user_name, qb.purchase_order_id, qb.purchase_order_code,qb.qc_status, qb.qc_date,qb.supplier_id,qb.warehouse_id, qb.create_user_name,qb.create_time, qi.qc_type,qi.is_inside, qp.sku_id,qp.sku_no,qi.total_qty, qi.qc_qty,qi.qc_good_qty, qi.qc_bad_qty,qi.qc_result, qi.handle_mode_dict, qi.bad_description, qi.qc_good_rate*100 AS qcGoodRate, qi.qc_bad_rate*100 AS qcBadRate FROM qc_info qb LEFT JOIN qc_result qi ON qb.id=qi.main_id AND qi.is_deleted=FALSE LEFT JOIN qc_product qp ON qp.main_id=qi.main_id AND qp.is_deleted=FALSE WHERE qb.is_deleted=FALSE
AND qb.id IN
#{id}
AND qb.qc_status=#{params.searchType}
AND qb.purchase_order_code ilike concat('%', #{params.purchaseOrderCode} ,'%')
AND qb.code ilike concat('%', #{params.code} ,'%')
AND qp.sku_no IN
#{skuNo}
AND qb.qc_status IN
#{qcStatus}
AND qb.qc_user_id IN
#{qcUserId}
AND qi.qc_type =#{params.qcType}
AND qi.is_inside =#{params.isInside}
AND qb.supplier_id IN
#{supplierId}
AND qb.warehouse_id IN
#{warehouseId}
AND qi.qc_result IN
#{qcResult}
AND qi.handle_mode_dict IN
#{handleMode}
AND qb.create_user_id IN
#{createUserId}
AND qb.create_time >= #{params.createTimeList[0]} and (#{params.createTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > qb.create_time
${params.param}
ORDER BY qb.create_time DESC

SELECT qb.id AS sourceId, qb.purchase_order_id AS purchaseOrderId, qb.purchase_order_code AS purchaseOrderCode, qi.purchase_order_detail_id AS purchaseOrderDetailId, qp.sku_id AS skuId, qp.sku_no AS skuNo, qi.qc_bad_qty AS realityReturnQty FROM qc_info qb INNER JOIN qc_result qi ON qb.id=qi.main_id AND qi.is_deleted=FALSE INNER join qc_product qp ON qp.main_id=qi.main_id AND qb.is_deleted=FALSE WHERE qb.is_deleted=FALSE AND qb.purchase_order_id!=''
and qb.id in
#{item}
